import{_ as p,a0 as o,w as r,s as d,ao as l,I as t,x as s,a1 as n,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"修复 Debian 中的 vim 奇怪行为 | LCTT x X-CMD","titleTemplate":false,"description":"修复 Debian 中的 vim 奇怪行为 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"修复 Debian 中的 vim 奇怪行为 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"修复 Debian 中的 vim 奇怪行为 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171016 Fixing vim in Debian - There and back again","title":"修复 Debian 中的 vim 奇怪行为","tag":"201801","desc":""},"relativePath":"201801/20171016 Fixing vim in Debian - There and back again.md","filePath":"[post].md"}'),m={name:"201801/20171016 Fixing vim in Debian - There and back again.md"};function g(u,i,b,v,f,h){const e=o("Link");return r(),d("div",null,[i[16]||(i[16]=l('<h1 id="修复-debian-中的-vim-奇怪行为" tabindex="-1">修复 Debian 中的 vim 奇怪行为 <a class="header-anchor" href="#修复-debian-中的-vim-奇怪行为" aria-label="Permalink to “修复 Debian 中的 vim 奇怪行为”">​</a></h1><p>我一直在想，为什么我服务器上 vim 为什么在鼠标方面表现得如此愚蠢：不能像平时那样跳转、复制、粘贴。尽管在 <code>/etc/vim/vimrc.local</code> 中已经设置了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>set mouse=</span></span></code></pre></div>',3)),t("p",null,[i[1]||(i[1]=s("最后我终于知道为什么了，多谢 bug ",-1)),n(e,{href:"https://bugs.debian.org/cgi-bin/bugreport.cgi?bug=864074"},{default:a(()=>[...i[0]||(i[0]=[s("#864074",-1)])]),_:1}),i[2]||(i[2]=s(" 并且修复了它。",-1))]),i[17]||(i[17]=l(`<p><img src="https://www.preining.info/blog/wp-content/uploads/2017/10/fixing-debian-vim.jpg" alt=""></p><p>原因是，当没有 <code>~/.vimrc</code> 的时候，vim 在 <code>vimrc.local</code> <strong>之后</strong>加载 <code>defaults.vim</code>，从而覆盖了几个设置。</p><p>在 <code>/etc/vim/vimrc</code> 中有一个注释（虽然我没有看到）解释了这一点：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot; Vim will load $VIMRUNTIME/defaults.vim if the user does not have a vimrc.</span></span>
<span class="line"><span>&quot; This happens after /etc/vim/vimrc(.local) are loaded, so it will override</span></span>
<span class="line"><span>&quot; any settings in these files.</span></span>
<span class="line"><span>&quot; If you don&#39;t want that to happen, uncomment the below line to prevent</span></span>
<span class="line"><span>&quot; defaults.vim from being loaded.</span></span>
<span class="line"><span>&quot; let g:skip_defaults_vim = 1</span></span></code></pre></div><p>我同意这是在正常安装 vim 后设置 vim 的好方法，但 Debian 包可以做得更好。在错误报告中清楚地说明了这个问题：如果没有 <code>~/.vimrc</code>，<code>/etc/vim/vimrc.local</code> 中的设置被覆盖。</p><p>这在Debian中是违反直觉的 - 而且我也不知道其他包中是否采用类似的方法。</p><p>由于 <code>defaults.vim</code> 中的设置非常合理，所以我希望使用它，但只修改了一些我不同意的项目，比如鼠标。最后，我在 <code>/etc/vim/vimrc.local</code> 中做了以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if filereadable(&quot;/usr/share/vim/vim80/defaults.vim&quot;)</span></span>
<span class="line"><span>  source /usr/share/vim/vim80/defaults.vim</span></span>
<span class="line"><span>endif</span></span>
<span class="line"><span>&quot; now set the line that the defaults file is not reloaded afterwards!</span></span>
<span class="line"><span>let g:skip_defaults_vim = 1</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>&quot; turn of mouse</span></span>
<span class="line"><span>set mouse=</span></span>
<span class="line"><span>&quot; other override settings go here</span></span></code></pre></div><p>可能有更好的方式来获得一个不依赖于 vim 版本的通用加载语句, 但现在我对此很满意。</p><hr>`,10)),t("p",null,[i[4]||(i[4]=s("via: ",-1)),n(e,{href:"https://www.preining.info/blog/2017/10/fixing-vim-in-debian/"},{default:a(()=>[...i[3]||(i[3]=[s("https://www.preining.info/blog/2017/10/fixing-vim-in-debian/",-1)])]),_:1})]),t("p",null,[i[8]||(i[8]=s("作者：",-1)),n(e,{href:"https://www.preining.info/blog/author/norbert/"},{default:a(()=>[...i[5]||(i[5]=[s("Norbert Preining",-1)])]),_:1}),i[9]||(i[9]=s(" 译者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:a(()=>[...i[6]||(i[6]=[s("geekpi",-1)])]),_:1}),i[10]||(i[10]=s(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:a(()=>[...i[7]||(i[7]=[s("wxy",-1)])]),_:1})]),t("p",null,[i[13]||(i[13]=s("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[11]||(i[11]=[s("LCTT",-1)])]),_:1}),i[14]||(i[14]=s(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:a(()=>[...i[12]||(i[12]=[s("Linux中国",-1)])]),_:1}),i[15]||(i[15]=s(" 荣誉推出",-1))])])}const x=p(m,[["render",g]]);export{T as __pageData,x as default};
